{
  "name": "opencode-presets",
  "version": "0.38.4",
  "description": "Interactive CLI that patches OpenCode config files with curated presets — MCP, permissions, plugins, skills.",
  "type": "module",
  "bin": {
    "opencode-presets": "dist/bin/opencode-presets.js"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/trick77/opencode-presets.git"
  },
  "homepage": "https://github.com/trick77/opencode-presets#readme",
  "bugs": {
    "url": "https://github.com/trick77/opencode-presets/issues"
  },
  "files": [
    "dist/",
    "presets/",
    "README.md",
    "AGENTS.md"
  ],
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsc",
    "watch": "tsc --watch",
    "test": "tsc && node --test dist/test/*.test.js",
    "coverage": "tsc && node --test --experimental-test-coverage dist/test/*.test.js",
    "check-pins": "tsc && node scripts/check-pins.mjs",
    "check-fetch-hashes": "tsc && node scripts/check-fetch-hashes.mjs",
    "prepare": "tsc",
    "prepublishOnly": "tsc"
  },
  "dependencies": {
    "ajv": "8.20.0",
    "chalk": "6.0.1"
  },
  "devDependencies": {
    "@types/node": "26.6.6",
    "typescript": "7.0.2"
  },
  "license": "MIT",
  "keywords": [
    "opencode",
    "presets",
    "mcp",
    "config"
  ]
}
